def _builder_code_step(vars):
 import json
 import datetime
 import re
 keys = ['turn_raw', 'turn_decision', 'turn_name', 'turn_topics', 'turn_scope', 'turn_amount', 'turn_date', 'turn_date_kind', 'turn_date_words', 'turn_time', 'turn_answer', 'turn_terms', 'turn_question', 'turn_change_evidence', 'turn_paid_evidence', 'turn_dispute_evidence', 'turn_no_talk_evidence']
 t = dict(((k, vars.get(k, '')) for k in keys))
 for k in keys:
  vars[k] = ''
 vars['route'] = 'dialogue'
 vars['message'] = 'Please clarify your response.'
 vars['pending_offer'] = ''
 try:

  def obj(x, fallback):
   if isinstance(x, str):
    try:
     v = json.loads(x)
     return v if isinstance(v, type(fallback)) else fallback
    except Exception:
     return fallback
   return x if isinstance(x, type(fallback)) else fallback

  def yes(x):
   return str(x).lower() == 'true'
  s = obj(vars.get('state', '{}'), {})
  ps = s.get('products', [])
  for k in ['notices', 'pending_clauses', 'confirmation_batch']:
   s.setdefault(k, [])
  now = datetime.datetime.fromisoformat(str(vars.get('now', '')))
  today = now.date()
  holidays = {'2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01'}

  def business(d):
   return d.weekday() < 5 and d.isoformat() not in holidays

  def next_business(d):
   while not business(d):
    d += datetime.timedelta(days=1)
   return d

  def after(n):
   d = today
   for unused in range(n):
    d = next_business(d + datetime.timedelta(days=1))
   return d
  monday = today - datetime.timedelta(days=today.weekday())

  def last_business(m):
   d = m + datetime.timedelta(days=4)
   while not business(d):
    d -= datetime.timedelta(days=1)
   return d
  attempt_day = last_business(monday)
  if attempt_day <= today:
   attempt_day = last_business(monday + datetime.timedelta(days=7))

  def norm(x):
   return re.sub('[^a-z0-9]+', ' ', str(x).lower()).strip()

  def present(e, raw):
   return bool(norm(e)) and norm(e) in norm(raw)
  weekdays = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']
  months = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december']
  ordinals = ['first', 'second', 'third', 'fourth', 'fifth', 'sixth', 'seventh', 'eighth', 'ninth', 'tenth', 'eleventh', 'twelfth', 'thirteenth', 'fourteenth', 'fifteenth', 'sixteenth', 'seventeenth', 'eighteenth', 'nineteenth', 'twentieth', 'twenty first', 'twenty second', 'twenty third', 'twenty fourth', 'twenty fifth', 'twenty sixth', 'twenty seventh', 'twenty eighth', 'twenty ninth', 'thirtieth', 'thirty first']
  wp = '(?:' + '|'.join(weekdays) + ')'
  mp = '(?:' + '|'.join(months) + ')'
  op = '(?:' + '|'.join((re.escape(x).replace('\\ ', '[ -]') for x in sorted(ordinals, key=lambda x: -len(x)))) + ')'
  cardinals = ['one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen', 'seventeen', 'eighteen', 'nineteen', 'twenty', 'twenty one', 'twenty two', 'twenty three', 'twenty four', 'twenty five', 'twenty six', 'twenty seven', 'twenty eight', 'twenty nine', 'thirty', 'thirty one']
  day_names = dict(((name, i + 1) for names in [ordinals, cardinals] for i, name in enumerate(names)))
  cp = '(?:' + '|'.join((re.escape(x).replace('\\ ', '[ -]') for x in sorted(cardinals, key=lambda x: -len(x)))) + ')'
  dp = '(?:' + op + '|' + cp + '|\\d{1,2}(?:st|nd|rd|th)?)'
  date_pattern = '\\b(?:day after tomorrow|tomorrow|today|(?:next|this)\\s+' + wp + '|\\d{4}-\\d{2}-\\d{2}|\\d{1,2}[/.]\\d{1,2}[/.]\\d{4}|' + dp + '\\s+(?:of\\s+)?' + mp + '(?:\\s+\\d{4})?|' + mp + '\\s+' + dp + '(?:\\s+\\d{4})?|' + wp + ')\\b'
  calendar_day = '(?:the\\s+)?' + dp
  calendar_body = '(?:\\d{4}-\\d{2}-\\d{2}|\\d{1,2}[/.]\\d{1,2}[/.]\\d{4}|' + calendar_day + '\\s+(?:of\\s+)?' + mp + '(?:,?\\s+\\d{4})?|' + mp + '\\s+' + calendar_day + '(?:,?\\s+\\d{4})?|the\\s+' + dp + ')'
  date_pattern = '\\b(?:day after tomorrow|tomorrow|today|(?:next|this)\\s+' + wp + '|' + wp + '\\s*,?\\s+(?:' + calendar_body + '|' + calendar_day + ')|' + calendar_body + '|' + wp + ')\\b'

  def literal_date(raw):
   try:
    return datetime.date.fromisoformat(str(raw)[:10])
   except Exception:
    return False

  def parse_date_words(words):
   text = re.sub('^on\\s+', '', str(words).lower().strip().rstrip('.!?'))
   try:
    if text in ['today', 'tomorrow', 'day after tomorrow']:
     return today + datetime.timedelta(days=['today', 'tomorrow', 'day after tomorrow'].index(text))
    relative = re.fullmatch('(next|this)\\s+(' + '|'.join(weekdays) + ')', text)
    if relative:
     return monday + datetime.timedelta(days=weekdays.index(relative.group(2)) + (7 if relative.group(1) == 'next' else 0))
    if text in weekdays:
     return today + datetime.timedelta(days=(weekdays.index(text) - today.weekday()) % 7)
    mentioned = [i for i, w in enumerate(weekdays) if re.search('\\b' + w + '\\b', text)]
    if len(mentioned) > 1:
     return False
    weekday = mentioned[0] if mentioned else -1
    if mentioned:
     text = re.sub('\\b' + weekdays[weekday] + '\\b', ' ', text).strip(' ,')

    def checked(d):
     return d if weekday < 0 or d.weekday() == weekday else False
    if re.fullmatch('\\d{4}-\\d{2}-\\d{2}', text):
     return checked(datetime.date.fromisoformat(text))
    numeric = re.fullmatch('(\\d{1,2})[/.](\\d{1,2})[/.](\\d{4})', text)
    if numeric:
     a, b, y = [int(v) for v in numeric.groups()]
     possible = set()
     for day, month in [(a, b), (b, a)]:
      try:
       d = checked(datetime.date(y, month, day))
       if d:
        possible.add(d)
      except Exception:
       pass
     return next(iter(possible)) if len(possible) == 1 else False
    text = ' '.join(text.replace('-', ' ').replace(',', ' ').split())

    def day_number(word):
     return day_names[word] if word in day_names else int(re.sub('(st|nd|rd|th)$', '', word))
    for month in months:
     if re.search('\\b' + month + '\\b', text):
      a = re.fullmatch('(?:the\\s+)?(' + dp + ')\\s+(?:of\\s+)?' + month + '(?:\\s+(\\d{4}))?', text)
      b = re.fullmatch(month + '\\s+(?:the\\s+)?(' + dp + ')(?:\\s+(\\d{4}))?', text)
      match = a or b
      if not match:
       return False
      day = day_number(match.group(1))
      year = int(match.group(2)) if match.group(2) else today.year
      d = datetime.date(year, months.index(month) + 1, day)
      if not match.group(2) and d < today:
       d = datetime.date(year + 1, months.index(month) + 1, day)
      return checked(d)
    match = re.fullmatch('(?:the\\s+)?(' + dp + ')', text)
    if match:
     day = day_number(match.group(1))
     for offset in [0, 1]:
      year, month_zero = divmod(today.year * 12 + today.month - 1 + offset, 12)
      try:
       d = datetime.date(year, month_zero + 1, day)
      except Exception:
       continue
      if d >= today:
       return checked(d)
   except Exception:
    return False
   return False

  def amount_shaped_day(match, text):
   bare_day = bool(re.fullmatch('the\\s+' + dp, match.group(0)))
   money_suffix = bool(re.match('(?:[.,]\\d|\\s+(?:dollars?|pounds?|euros?|cents?|pence)\\b)', text[match.end():]))
   payment_amount = bool(re.search('\\b(?:pay|paying|paid|send|sending|amount(?: of)?|sum(?: of)?)\\s+$', text[:match.start()]))
   return bare_day and (money_suffix or payment_amount)

  def strip_dates(text):
   return re.sub(date_pattern, lambda match: match.group(0) if amount_shaped_day(match, text) else ' ', text)

  def date_candidates(raw):
   positive, negative = ([], [])
   for segment in re.split('\\b(?:but|however|instead|rather than)\\b|[,;!?]', str(raw).lower()):
    previous_end = 0
    for m in re.finditer(date_pattern, segment):
     context = segment[previous_end:m.start()]
     previous_end = m.end()
     if amount_shaped_day(m, segment):
      continue
     negated = bool(re.search("\\b(?:not|cannot|can't|cant|won't|wont|couldn't|couldnt|unable|never|except)\\b", context))
     (negative if negated else positive).append(m.group(0))
   return (positive, negative)

  def date_value(raw, words=''):
   if words and parse_date_words(words):
    return parse_date_words(words)
   if words:
    positive, negative = date_candidates(words)
    parsed = [parse_date_words(w) for w in positive]
    parsed = [d for d in parsed if d]
    if len(set((d.isoformat() for d in parsed))) > 1:
     return False
    if parsed:
     return parsed[0]
    return False
   return literal_date(raw)

  def spoken_date(raw):
   d = literal_date(raw)
   return months[d.month - 1].capitalize() + ' ' + str(d.day) + ', ' + str(d.year) if d else str(raw)
  prefix = []

  def save_prefix():
   if prefix:
    s['notices'].extend(prefix)
    prefix.clear()

  def speak(text, phase='', offer=''):
   if phase:
    s['phase'] = phase
   vars['route'] = 'dialogue'
   vars['message'] = ' '.join(dict.fromkeys(s['notices'] + prefix + [text]))
   s['notices'] = []
   prefix.clear()
   vars['pending_offer'] = offer
   vars['last_core_message'] = text

  def clarify_pending(text='Please clarify whether you accept or decline the pending offer.'):
   core = vars.get('last_core_message', '')
   offer = vars.get('last_offer', '')
   speak(text, s['phase'], offer)
   vars['last_core_message'] = core

  def api(kind, body):
   save_prefix()
   vars['route'] = kind
   for k, v in body.items():
    vars['request_' + k] = v

  def signature(p):
   return str(float(p['amount'])) + '|' + str(p['date'])

  def valid(p):
   d = literal_date(p.get('date', ''))
   return bool(not p.get('date_conflict') and d and (today <= d <= literal_date(p['deadline'])) and business(d) and (p['floor'] <= float(p['amount']) <= p['past_due']))

  def invalidate():
   s['confirmation_batch'] = []
   for p in ps:
    if p['status'] != 'recorded':
     p['confirmed'] = ''

  def exclude(i, reason):
   p = ps[i]
   if p['status'] != 'recorded':
    p.update(status='excluded', reason=reason, confirmed='', pending_kind='', pending_text='', date_conflict=False)

  def finish(outcome='', reason=''):
   if outcome != 'transferred' and (not s.get('transfer_requested')) and any((p.get('status') == 'agreed' and p.get('confirmed') == signature(p) for p in ps)):
    s['finish_after_writes'] = True
    write_next()
    return
   if outcome:
    s['outcome'], s['reason'] = (outcome, reason)
   s['terminal'] = True
   s['phase'] = 'finalizing'
   if ps and s.get('outcome') != 'transferred':
    for i, p in enumerate(ps):
     if p['status'] != 'recorded' and (not p.get('reason')):
      exclude(i, 'refused')
    if any((p['status'] == 'recorded' for p in ps)):
     s['outcome'], s['reason'] = ('promise', '')
    elif all((p.get('reason') == 'paid' for p in ps)):
     s['outcome'], s['reason'] = ('paid', '')
    else:
     s['outcome'], s['reason'] = ('no_promise', next((p['reason'] for p in ps if p.get('reason') != 'paid')))
   save_prefix()
   if s.get('mode') == 'B' and (not s.get('transfer_requested')):
    for i, p in enumerate(ps):
     if p['status'] != 'recorded' and (not p.get('note_done')) and not p.get('note_attempted', False):
      s['note_index'] = i
      p['note_attempted'] = True
      api('add_note', dict(product_id=p['product_id'], reason=p['reason']))
      return
   vars['outcome'] = s.get('outcome') or ('no_promise' if s.get('verified') else 'not_verified')
   vars['reason'] = s.get('reason') or ('service_error' if s.get('verified') else 'declined')
   if vars['outcome'] in ['promise', 'paid']:
    vars['reason'] = ''
   vars['farewell'] = ' '.join(dict.fromkeys(s['notices'] + ['Thank you. Goodbye.']))
   s['notices'] = []
   vars['route'] = 'farewell'

  def targets(scope, default_all=False):
   text = str(scope or '').strip()
   if not text:
    return []
   n = norm(text)
   if n in ['all', 'everything', 'all products', 'all of them', 'all three', 'both', 'both products']:
    return list(range(len(ps)))
   if n in ['current', 'this', 'that', 'it', 'this product']:
    return list(range(len(ps))) if default_all else [s.get('active', 0)] if ps else []
   exact = [i for i, p in enumerate(ps) if text == str(p['product_id'])]
   if exact:
    return exact
   if ',' in text:
    out = []
    for part in text.split(','):
     found = targets(part, False)
     if not found:
      return []
     out.extend(found)
    return list(dict.fromkeys(out))
   if n in ['loans', 'both loans', 'the loans', 'all loans']:
    return [i for i, p in enumerate(ps) if p['type'] in ['personal_loan', 'car_loan']]
   matches = [i for i, p in enumerate(ps) if n in set((norm(a) for a in p.get('aliases', [])))]
   if matches:
    return matches
   cleaned = ' '.join(re.sub('\\b(my|the|your|product|account)\\b', ' ', n).split())
   return [i for i, p in enumerate(ps) if cleaned in set((norm(a) for a in p.get('aliases', [])))]

  def scoped(scope, default_all=False):
   found = targets(scope, default_all)
   n = norm(scope)
   plural = n in ['all', 'everything', 'all products', 'all of them', 'all three', 'both', 'both products', 'loans', 'both loans', 'the loans', 'all loans'] or ',' in str(scope) or (n in ['current', ''] and default_all)
   return found if len(found) == 1 or plural else []

  def literal_scope(text):
   n = norm(text)
   if re.search('\\b(all of them|all products|all three|both products|everything|both|all)\\b', n) and (not re.search('\\b(not all|not both|except|excluding)\\b', n)):
    return 'all'
   found = []
   specific_loan = any((re.search('\\b' + re.escape(norm(a)) + '\\b', n) for p in ps for a in p.get('aliases', []) if norm(a) in ['personal loan', 'car loan', 'auto loan', 'vehicle loan']))
   for i, p in enumerate(ps):
    aliases = [norm(a) for a in p.get('aliases', []) if norm(a)]
    if specific_loan:
     aliases = [a for a in aliases if a != 'loan']
    if any((re.search('\\b' + re.escape(a) + '\\b', n) for a in aliases)):
     found.append(i)
   if len(found) == 1:
    return ps[found[0]]['product_id']
   if len(found) > 1 and (not (n == 'loan' or n == 'the loan')):
    return ','.join((ps[i]['product_id'] for i in found))
   return ''

  def queue_offer(i, kind, text=''):
   ps[i].update(status='open', confirmed='', pending_kind=kind, pending_text=text)

  def display_offer(i):
   p = ps[i]
   s['active'] = i
   kind = p.get('pending_kind') or p.get('offer_kind', 'proposal')
   text = p.get('pending_text', '') or 'Can you pay ' + str(p['amount']) + ' for your ' + p['label'] + ' on ' + spoken_date(p['date']) + '?'
   p['offer_kind'] = kind
   p['pending_kind'], p['pending_text'] = ('', '')
   speak(text, 'negotiate', p['label'] + ': ' + str(p['amount']) + ' on ' + p['date'] + '; ' + kind + ', not final confirmation.')

  def persuade(i):
   p = ps[i]
   if p.get('hardship'):
    exclude(i, 'hardship')
    return False
   while p['attempts'] < p['budget']:
    p['attempts'] += 1
    p['amount'] = (p['floor'] if p.get('unaffordable') else p['past_due']) if p['attempts'] == 1 else p['floor']
    p['date'] = attempt_day.isoformat() if p['attempts'] == 1 else p['deadline']
    p['date_conflict'] = False
    if signature(p) in p['refused']:
     continue
    rest = ' The rest stays overdue.' if p['amount'] < p['past_due'] else ''
    queue_offer(i, 'persuasion', 'Can you pay ' + str(p['amount']) + ' for your ' + p['label'] + ' on ' + spoken_date(p['date']) + '?' + rest)
    return True
   exclude(i, 'refused')
   return False

  def readback():
   agreed = [p for p in ps if p['status'] == 'agreed']
   if not agreed:
    finish()
    return
   lines, batch = ([], [])
   for p in agreed:
    if not valid(p):
     queue_offer(ps.index(p), 'date_needed', 'Please name an exact business day today or later, no later than ' + spoken_date(p['deadline']) + ', for your ' + p['label'] + '.')
     display_offer(ps.index(p))
     return
    p['confirmed'] = ''
    batch.append(dict(product_id=p['product_id'], amount=p['amount'], date=p['date'], signature=signature(p)))
    extra = ' This is its own latest recordable date, instead of your common requested date.' if p.get('common_adjusted') else ''
    lines.append(p['label'] + ': ' + str(p['amount']) + ' on ' + spoken_date(p['date']) + '.' + extra)
   s['confirmation_batch'] = batch
   s['readback_text'] = ' '.join(lines) + ' Do you confirm?'
   speak(s['readback_text'], 'confirm', 'One confirmation of this exact batch with EACH product own amount/date: ' + json.dumps(batch))

  def progress():
   if s['pending_clauses']:
    c = s['pending_clauses'][0]
    speak('Which product do you mean by ' + str(c.get('scope', 'that reference')) + ': ' + ', '.join((p['label'] for p in ps)) + '? Your other choices are retained.', 'resolve_product', 'Clarify only the ambiguous product reference.')
    return
   for i, p in enumerate(ps):
    if p['status'] == 'open':
     if p.get('pending_kind'):
      display_offer(i)
      return
     if persuade(i):
      display_offer(i)
      return
   readback()

  def transfer(queue):
   s['transfer_requested'] = True
   s['queue'] = queue
   invalidate()
   s['pending_clauses'] = []
   api('transfer_to_agent', dict(queue=queue))

  def support(indices):
   s['support_targets'] = indices
   s['resume_phase'] = s['phase']
   speak('I am sorry you are going through this. Would you like me to connect you with our customer support team?', 'support', 'ONLY support transfer, not a payment offer.')

  def propose(i, c, common=False):
   p = ps[i]
   if p['status'] == 'recorded':
    prefix.append('You can change a recorded promise in the mobile app. It cannot be changed or cancelled in this call.')
    return
   p['confirmed'] = ''
   disp = c.get('disposition', '')
   if disp in ['paid', 'dispute']:
    exclude(i, disp)
    if disp == 'paid':
     prefix.append('Payments can take one business day to appear.')
    return
   if disp == 'hardship':
    p['hardship'] = True
   amount = p['past_due'] if c.get('amount_reference') == 'full' else p['floor'] if c.get('amount_reference') == 'floor' else p['amount']
   if c.get('amount', '') != '':
    try:
     amount = float(c['amount'])
    except Exception:
     pass
   too_much = disp == 'too_much'
   if too_much or amount < p['floor']:
    p['unaffordable'] = True
   supplied_date = bool(c.get('date') or c.get('date_words') or c.get('date_kind') == 'exact' or c.get('date_conflict'))
   d = date_value(c.get('date', ''), c.get('date_words', ''))
   if c.get('date_conflict') or (supplied_date and (not d)):
    p['date_conflict'] = True
    if p['floor'] <= amount <= p['past_due']:
     p['amount'] = amount
    queue_offer(i, 'date_conflict', 'What exact date do you want to pay for your ' + p['label'] + '?')
    return
   if p.get('date_conflict') and (not d):
    queue_offer(i, 'date_conflict', 'What exact date do you want to pay for your ' + p['label'] + '?')
    return
   if d:
    p['date_conflict'] = False
    p['date'] = d.isoformat()
    p['common_adjusted'] = False
   date_issue = ''
   if c.get('date_kind') == 'vague':
    if not p['vague_asked']:
     p['vague_asked'] = True
     date_issue = 'exact_date'
    else:
     p['date'] = p['deadline']
     date_issue = 'deadline'
   d = literal_date(p['date'])
   deadline = literal_date(p['deadline'])
   if not d or d < today:
    date_issue = 'date_needed'
   elif d > deadline:
    p['date'] = p['deadline']
    if common and s['mode'] == 'B':
     p['common_adjusted'] = True
    else:
     date_issue = 'deadline'
   elif not business(d):
    p['date'] = min(next_business(d), deadline).isoformat()
    if common and s['mode'] == 'B':
     prefix.append('For ' + p['label'] + ', the next business day is ' + spoken_date(p['date']) + '.')
    else:
     date_issue = 'business_day'
   if too_much or amount < p['floor']:
    if amount < p['floor']:
     prefix.append('I cannot record an amount below ' + str(p['floor']) + ' for your ' + p['label'] + '.')
    if not p['floor_offered']:
     p['floor_offered'] = True
     p['amount'] = p['floor']
     if date_issue in ['date_needed', 'exact_date']:
      p['floor_pending'] = True
     else:
      queue_offer(i, 'floor', 'Can you pay ' + str(p['floor']) + ' for your ' + p['label'] + ' on ' + spoken_date(p['date']) + '? The rest stays overdue.')
      return
    else:
     persuade(i)
     return
   elif amount > p['past_due']:
